//****************************************************************************
// ENTITY CLASS for Assessments
//****************************************************************************
@ObjectType({ description: `One row per (Parcel, AssessmentYear, Source) — the assessment-history table. Carries both the original assessed value and, once a PTABOA appeal is decided, the post-appeal value, so a single year can show both an original and an appealed determination.` })
export class indianataxAssessment_ {
    @Field() 
    @MaxLength(36)
    ID: string;
        
    @Field({description: `The parcel this assessment belongs to.`}) 
    @MaxLength(36)
    ParcelID: string;
        
    @Field(() => Int, {description: `The assessment/payable year this row represents (Indiana assessments are dated January 1 of the assessment year).`}) 
    AssessmentYear: number;
        
    @Field({description: `Where this assessment row came from, e.g. dlgf_gdb_2025, marion_foia_2026. Identifies the data pull/vintage.`}) 
    @MaxLength(50)
    Source: string;
        
    @Field({nullable: true, description: `DLGF property class code as recorded for this specific assessment year (may differ from the parcel's current PropertyClassCode).`}) 
    @MaxLength(10)
    PropertyClassCode?: string;
        
    @Field(() => Float, {nullable: true, description: `Originally assessed land value for the year, before any appeal.`}) 
    OriginalLandAV?: number;
        
    @Field(() => Float, {nullable: true, description: `Originally assessed improvement value for the year, before any appeal.`}) 
    OriginalImprovementAV?: number;
        
    @Field(() => Float, {nullable: true, description: `Originally assessed total value for the year (land + improvement), before any appeal.`}) 
    OriginalTotalAV?: number;
        
    @Field(() => Float, {nullable: true, description: `Land value as revised after the original determination. For Marion sources: the value after a PTABOA appeal determination, NULL until an appeal on this parcel/year is decided. For a county-card source (Assessment.Source in scripts/lib/county-card-sources.js, e.g. LakePRC): the later certified column of the same year on the parcel's cards, whatever the county's reason -- an appeal form (Rev. 134, Det/115), a Form 113 notice, a re-trend, a split or a correction; the reason is CardValuationColumn.ReasonForChange / ReasonKind, and only ReasonKind = 'appeal' is an appeal outcome. NULL when no later column differs.`}) 
    PTABOALandAV?: number;
        
    @Field(() => Float, {nullable: true, description: `Improvement value as revised after the original determination. For Marion sources: the value after a PTABOA appeal determination, NULL until an appeal on this parcel/year is decided. For a county-card source (Assessment.Source in scripts/lib/county-card-sources.js, e.g. LakePRC): the later certified column of the same year on the parcel's cards, whatever the county's reason -- an appeal form (Rev. 134, Det/115), a Form 113 notice, a re-trend, a split or a correction; the reason is CardValuationColumn.ReasonForChange / ReasonKind, and only ReasonKind = 'appeal' is an appeal outcome. NULL when no later column differs.`}) 
    PTABOAImprovementAV?: number;
        
    @Field(() => Float, {nullable: true, description: `Total value as revised after the original determination. For Marion sources: the value after a PTABOA appeal determination, NULL until an appeal on this parcel/year is decided. For a county-card source (Assessment.Source in scripts/lib/county-card-sources.js, e.g. LakePRC): the later certified column of the same year on the parcel's cards, whatever the county's reason -- an appeal form (Rev. 134, Det/115), a Form 113 notice, a re-trend, a split or a correction; the reason is CardValuationColumn.ReasonForChange / ReasonKind, and only ReasonKind = 'appeal' is an appeal outcome. NULL when no later column differs.`}) 
    PTABOATotalAV?: number;
        
    @Field() 
    _mj__CreatedAt: Date;
        
    @Field() 
    _mj__UpdatedAt: Date;
        
    @Field({nullable: true, description: `The specific SourceDocument this assessment row was extracted from (the DLGF geodatabase pull, the Marion FOIA parcel-list CSV, or the parcel's Property Record Card). The free-text \`Source\` column is the short provenance label; this is the traceable document.`}) 
    @MaxLength(36)
    SourceDocumentID?: string;
        
    @Field(() => Int, {nullable: true, description: `County-card sources only. The form behind the PTABOA*AV revision (CardValuationColumn.ReasonForm of the later column): 134, 115, 133, 130, 131, 113 or NULL. NULL when nothing revised the year, or the revising column names no form (a re-trend, a split).`}) 
    RevisionForm?: number;
        
    @Field({nullable: true, description: `County-card sources only. The Reason For Change cell of the column that supplied PTABOA*AV, verbatim ('Rev. 134', 'F113', 'AA'). NULL when nothing revised the year.`}) 
    @MaxLength(50)
    RevisionReason?: string;
        
    @Field({nullable: true, description: `County-card sources only. The As Of Date of the column that supplied PTABOA*AV. NULL when nothing revised the year.`}) 
    RevisionAsOfDate?: Date;
        
    @Field() 
    @MaxLength(30)
    Parcel: string;
        
    @Field({nullable: true}) 
    @MaxLength(500)
    SourceDocument?: string;
        
}

