    SizeText?: string;
        
    @Field(() => Float, {nullable: true, description: `Abn Obs: abnormal obsolescence, percent. DepreciationObsolescence carries normal depreciation (Norm Dep).`}) 
    AbnormalObsolescencePct?: number;
        
